/* Provider keys stay on the local server in .env, never in this file. */
(()=>{
 const base=(window.CHWIJIK_API_BASE||'').replace(/\/$/,'');
 let corporation=null,business='',finance=null,jobs=null;
 const link=(url,label)=>{try{const u=new URL(url);if(!['https:','http:'].includes(u.protocol))return '';return `<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`}catch{return ''}};
 async function get(route,params={}){let response;try{response=await fetch(base+'/api/'+route+'?'+new URLSearchParams(params),{signal:AbortSignal.timeout(30000),credentials:'omit'})}catch{throw new Error('조회 서버에 연결할 수 없습니다. 로컬 서버가 실행 중인지 확인해 주세요.')}const data=await response.json().catch(()=>null);if(!data)throw new Error('실시간 조회 서버가 연결되지 않았습니다. 평가 기능은 그대로 이용할 수 있습니다.');if(!response.ok)throw new Error(data.error||'조회하지 못했습니다. 잠시 후 다시 시도해 주세요.');return data}
 function loading(title){showModal(title,'<p class="subtext" id="provider-status" role="status">공식 데이터 제공기관에 조회하고 있습니다…</p>','<button class="primary" id="provider-close">닫기</button>');$('#provider-close').onclick=closeModal;return $('#provider-status')}
 async function places(){const q=state.company.trim();if(q.length<2){toast('회사명을 두 글자 이상 입력해 주세요.');return}const status=loading('회사·사업장 주소 검색');try{const result=await get('places',{q});if(!status.isConnected)return;showModal('회사·사업장 선택',`<p class="subtext">카카오 로컬 검색 결과입니다. 본사와 실제 근무할 지점을 구분해 선택하세요.</p>${result.items.length?result.items.map((p,i)=>`<article class="review"><strong>${esc(p.name)}</strong><p>${esc(p.address)}</p>${link(p.url,'지도에서 확인')}<button class="full-btn" data-place="${i}">이 사업장 주소 입력</button></article>`).join(''):'<p class="notice">검색 결과가 없습니다. 지역이나 지점명을 함께 입력해 주세요.</p>'}`,`<button class="primary" id="place-close">닫기</button>`);$('#place-close').onclick=closeModal;document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{const p=result.items[+b.dataset.place];const parts=p.address.split(/\s+/);state.company=p.name;state.work=[parts[0]||'',parts[1]||'',parts.slice(2).join(' ')];state.workplace={name:p.name,address:p.address,x:p.x,y:p.y,url:p.url};corporation=null;finance=null;jobs=null;business='';closeModal();render();toast('사업장 주소를 입력했습니다.');})}catch(e){if(status.isConnected)status.textContent=e.message}}
 function corporateSearch(){showModal('DART 공시기업 선택',`<p class="subtext">같은 이름의 회사를 구분하기 위해 공시 법인을 선택합니다.</p><form id="corp-form"><label class="form-row" for="corp-name">법인명</label><input id="corp-name" type="text" value="${esc(state.company)}" minlength="2" maxlength="100" required><p id="corp-status" class="error" role="status"></p></form><div id="corp-results"></div>`,`<button class="primary" id="corp-submit">공시기업 검색</button>`);$('#corp-submit').onclick=()=>$('#corp-form').requestSubmit();$('#corp-form').onsubmit=async e=>{e.preventDefault();const status=$('#corp-status'),target=$('#corp-results'),button=$('#corp-submit');status.textContent='DART 기업목록 조회 중…';button.disabled=true;try{const data=await get('corporations',{q:$('#corp-name').value});if(!target.isConnected)return;status.textContent=data.items.length?'사업장 이름이 아닌 해당 법인을 선택하세요.':'일치하는 공시기업이 없습니다. 미공시 기업은 재무 수치를 제공하지 않습니다.';target.innerHTML=data.items.map((c,i)=>`<button class="full-btn" data-corp="${i}">${esc(c.name)} ${c.stock?'· 종목 '+esc(c.stock):'· 비상장 공시기업'}</button>`).join('');target.querySelectorAll('[data-corp]').forEach(b=>b.onclick=()=>{corporation=data.items[+b.dataset.corp];finance=null;financeForm()})}catch(err){if(status.isConnected)status.textContent=err.message}finally{if(button.isConnected)button.disabled=false}}}
 function financeForm(){if(!corporation){corporateSearch();return}const previous=new Date().getFullYear()-1;showModal('DART 재무 수치',`<p class="subtext">선택 법인: <b>${esc(corporation.name)}</b><br>연결재무제표와 별도재무제표를 섞지 않고 연간 사업보고서 기준으로 조회합니다.</p><form id="finance-form"><div class="form-pair"><div class="form-row"><label for="finance-year">사업연도</label><input id="finance-year" type="number" min="2015" max="${new Date().getFullYear()}" value="${finance?.year||previous}" required></div><div class="form-row"><label for="finance-division">재무제표 구분</label><select id="finance-division"><option value="CFS">연결</option><option value="OFS">별도</option></select></div></div><p class="error" id="finance-status" role="status"></p></form>`,`<button class="secondary" id="corp-change">다른 법인</button><button class="primary" id="finance-submit">공시 수치 조회</button>`);$('#corp-change').onclick=corporateSearch;$('#finance-submit').onclick=()=>$('#finance-form').requestSubmit();$('#finance-form').onsubmit=async e=>{e.preventDefault();const status=$('#finance-status'),button=$('#finance-submit');status.textContent='OpenDART 공시 조회 중…';button.disabled=true;try{const data=await get('finance',{code:corporation.code,year:$('#finance-year').value,division:$('#finance-division').value});if(!status.isConnected)return;finance=data;business=data.businessNumber||business;showFinance()}catch(err){if(status.isConnected)status.textContent=err.message}finally{if(button.isConnected)button.disabled=false}}}
 function showFinance(){const names={revenue:'매출액',operatingProfit:'영업이익',netProfit:'당기순이익',liabilities:'부채총계',equity:'자본총계'};showModal('기업 전망 · DART 근거',`<p class="subtext"><b>${esc(finance.company||corporation.name)}</b> · ${finance.year}년 사업보고서 · ${finance.division==='CFS'?'연결':'별도'}<br>금융감독원 OpenDART · 조회 ${esc(new Date(finance.fetchedAt).toLocaleString('ko-KR'))}</p>${finance.empty?'<p class="notice">해당 연도·재무제표 구분의 공시가 없습니다. 다른 연도 또는 연결/별도 구분으로 조회하세요.</p>':`<div class="box"><h3>공시 원본 수치</h3>${Object.entries(names).map(([k,name])=>{const m=finance.metrics[k];return `<div class="detail-row"><span>${name}</span><span>${m?.value!==null&&m?.value!==undefined?m.value.toLocaleString('ko-KR')+' '+esc(m.currency||'통화 미제공'):'미제공'}${m?.receipt?'<br>'+link('https://dart.fss.or.kr/dsaf001/main.do?rcpNo='+encodeURIComponent(m.receipt),'공시 원문'):''}</span></div>`}).join('')}</div><div class="box"><h3>같은 공시 기준으로 계산</h3>${[['매출 증감률',finance.ratios.revenueGrowth,'(당기−전기) ÷ 전기 × 100'],['영업이익률',finance.ratios.operatingMargin,'영업이익 ÷ 매출 × 100'],['부채비율',finance.ratios.debtRatio,'부채총계 ÷ 자본총계 × 100']].map(([name,value,formula])=>`<div class="detail-row"><span>${name}<br><small>${formula}</small></span><b>${value===null?'계산 불가':value+'%'}</b></div>`).join('')}</div>`}<p class="notice">공시 수치는 평가 점수와 구분한 원본 참고자료입니다. 분모가 0 이하이거나 자료·통화가 일치하지 않으면 비율을 계산하지 않습니다. 수치만으로 미래 성장이나 고용 안정을 보장하지 않습니다.</p>`,`<button class="secondary" id="finance-again">조회 조건 변경</button><button class="primary" id="finance-done">닫기</button>`);$('#finance-again').onclick=financeForm;$('#finance-done').onclick=closeModal}
 function jobsForm(){showModal('실제 채용공고·급여 이력',`<p class="subtext">고용24 사업자등록번호로 해당 기업을 정확히 조회합니다. DART 법인을 먼저 선택하면 공시된 사업자번호를 가져옵니다.</p><form id="jobs-form"><div class="form-row"><label for="jobs-business">사업자등록번호</label><input id="jobs-business" type="text" inputmode="numeric" pattern="[0-9-]{10,12}" value="${esc(business)}" placeholder="10자리 사업자등록번호" required></div><p id="jobs-status" class="error" role="status"></p></form>`,`<button class="secondary" id="jobs-dart">DART 법인 찾기</button><button class="primary" id="jobs-submit">실제 공고 조회</button>`);$('#jobs-dart').onclick=corporateSearch;$('#jobs-submit').onclick=()=>$('#jobs-form').requestSubmit();$('#jobs-form').onsubmit=async e=>{e.preventDefault();const status=$('#jobs-status'),button=$('#jobs-submit');business=$('#jobs-business').value.replace(/-/g,'');status.textContent='고용24 공고 조회 중…';button.disabled=true;try{const data=await get('jobs',{business});if(!status.isConnected)return;jobs=data;showJobs()}catch(err){if(status.isConnected)status.textContent=err.message}finally{if(button.isConnected)button.disabled=false}}}
 function showJobs(){const jobHTML=(j,history=false)=>`<article class="review"><strong>${esc(j.title||'제목 미제공')}</strong><p>${esc(j.company||'')} · ${esc(j.region||'지역 미제공')}<br>급여: ${esc(j.payType||'형태 미제공')} · ${esc(j.pay||'미제공')}<br>등록: ${esc(j.registered||'미제공')} · 마감: ${esc(j.closing||'미제공')}${history?'<br>최초 수집: '+esc(new Date(j.firstSeen).toLocaleDateString('ko-KR')):''}</p>${link(j.url,'공고 원문')}${history&&j.versions?.length>1?'<p>이 공고의 수집 이력</p>'+j.versions.map(v=>`<p>${esc(new Date(v.observedAt).toLocaleDateString('ko-KR'))}: ${esc(v.value.payType||'')} ${esc(v.value.pay||'미제공')}</p>`).join(''):''}</article>`;showModal('채용공고 · 고용24',`<p class="subtext">조회: ${esc(new Date(jobs.fetchedAt).toLocaleString('ko-KR'))}<br>제공기관 검색 결과 ${jobs.total??'미제공'}건 · 현재 페이지 ${jobs.items.length}건<br>이 서버에서 수집한 고유 공고 ${jobs.history.length}건</p><p class="notice">${esc(jobs.notice)} 과거 전체 이력은 소급 복원하지 않습니다. 현재 API 미노출은 마감·삭제로 단정하지 않습니다.</p><h4>현재 API 조회 결과</h4>${jobs.items.length?jobs.items.map(j=>jobHTML(j)).join(''):'<p class="empty">조회되는 공고가 없습니다.</p>'}${jobs.total>jobs.page*100?'<button class="full-btn" id="jobs-next">다음 공고 페이지</button>':''}<details><summary>수집된 과거 급여·공고 이력 보기</summary>${jobs.history.length?jobs.history.map(j=>jobHTML(j,true)).join(''):'<p class="empty">수집한 이력이 아직 없습니다.</p>'}</details>`,`<button class="secondary" id="jobs-again">다른 기업</button><button class="primary" id="jobs-done">닫기</button>`);$('#jobs-done').onclick=closeModal;$('#jobs-again').onclick=jobsForm;if($('#jobs-next'))$('#jobs-next').onclick=async()=>{const button=$('#jobs-next');button.disabled=true;try{jobs=await get('jobs',{business,page:jobs.page+1});showJobs()}catch(e){toast(e.message);button.disabled=false}}}
 function paint(){const company=$('#company');if(company&&!$('#find-workplace')){const button=document.createElement('button');button.id='find-workplace';button.type='button';button.className='full-btn';button.textContent='⌕ 회사·사업장 이름으로 주소 찾기';button.onclick=places;company.after(button);company.addEventListener('input',()=>{corporation=null;business='';finance=null;jobs=null});company.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();state.company=company.value;places()}})}if(state.step===3&&!$('#official-data')){const panel=document.createElement('section');panel.id='official-data';panel.className='box';panel.innerHTML='<h3>기업 공식 정보 <small>전용 API 조회</small></h3><p class="subtext">실제 채용공고와 공시 재무 수치를 확인하세요.</p><div class="provider-actions"><button class="secondary" id="view-jobs">채용공고·급여 이력</button><button class="secondary" id="view-finance">DART 재무 수치</button></div>';$('.content').append(panel);$('#view-jobs').onclick=jobsForm;$('#view-finance').onclick=financeForm}}
 const previousRender=render;render=function(){previousRender();paint()};paint();
})();
